def detect_anomalies(prices, threshold=3.0):
    media = sum(prices) / len(prices)
    varianza = sum((p - media) ** 2 for p in prices) / len(prices)
    desv = varianza ** 0.5
    resultado = []
    for i in range(len(prices)):
        z = (prices[i] - media) / desv
        if abs(z) > threshold:
            resultado.append(i)
    return resultado

def detect_anomalies(prices, threshold=3.0):
    anomalias = []
    for i in range(len(prices)):
        if prices[i] > threshold:
            anomalias.append(i)
    return anomalias

